import time
import hashlib
import os
import threading
from collections import OrderedDict

# Configuration
MAX_REQUESTS_PER_WINDOW = 100
WINDOW_SIZE_SECONDS = 60
CACHE_MAX_SIZE = 1024
BAN_THRESHOLD = 500
BAN_DURATION = 3600

class SlidingWindowCounter:
    """Thread-safe sliding window rate limiter with overflow protection."""

    def __init__(self, max_requests, window_size):
        self._max_requests = max_requests
        self._window_size = window_size
        self._lock = threading.Lock()
        self._windows = {}  # key -> (prev_count, curr_count, window_start)

    def _get_window_key(self, timestamp):
        return int(timestamp // self._window_size)

    def _compute_rate(self, prev_count, curr_count, elapsed_ratio):
        """Compute weighted request rate across sliding window.
        Uses integer arithmetic to avoid floating point issues."""
        # Weight previous window by remaining portion
        prev_weight = int(prev_count * (100 - int(elapsed_ratio * 100))) 
        curr_weight = curr_count * 100
        # Total rate normalized to per-100 basis
        total = prev_weight + curr_weight
        return total

    def is_allowed(self, client_id, timestamp=None):
        """Check if request is allowed and increment counter.
        Returns (allowed: bool, current_rate: int, remaining: int)"""
        if timestamp is None:
            timestamp = time.time()

        with self._lock:
            window_key = self._get_window_key(timestamp)

            if client_id not in self._windows:
                self._windows[client_id] = (0, 1, window_key)
                return True, 1, self._max_requests - 1

            prev_count, curr_count, stored_window = self._windows[client_id]

            if window_key == stored_window:
                # Same window - increment
                new_count = curr_count + 1
                elapsed_ratio = (timestamp % self._window_size) / self._window_size
                rate = self._compute_rate(prev_count, new_count, elapsed_ratio)

                if rate > self._max_requests * 100:
                    return False, rate // 100, 0

                self._windows[client_id] = (prev_count, new_count, stored_window)
                return True, rate // 100, max(0, self._max_requests - (rate // 100))

            elif window_key == stored_window + 1:
                # Next window - rotate
                elapsed_ratio = (timestamp % self._window_size) / self._window_size
                rate = self._compute_rate(curr_count, 1, elapsed_ratio)

                if rate > self._max_requests * 100:
                    return False, rate // 100, 0

                self._windows[client_id] = (curr_count, 1, window_key)
                return True, rate // 100, max(0, self._max_requests - (rate // 100))

            else:
                # Window gap - reset
                self._windows[client_id] = (0, 1, window_key)
                return True, 1, self._max_requests - 1


class IPReputationCache:
    """LRU cache for IP reputation scores with ban tracking."""

    def __init__(self, max_size=CACHE_MAX_SIZE):
        self._cache = OrderedDict()
        self._max_size = max_size
        self._lock = threading.Lock()

    def get_reputation(self, ip_addr):
        with self._lock:
            if ip_addr in self._cache:
                self._cache.move_to_end(ip_addr)
                entry = self._cache[ip_addr]
                return entry
            return None

    def update_reputation(self, ip_addr, violation_score):
        """Update reputation score. Higher score = more suspicious.
        Score is clamped to uint16 range for storage efficiency."""
        with self._lock:
            if ip_addr in self._cache:
                self._cache.move_to_end(ip_addr)
                entry = self._cache[ip_addr]
                old_score = entry['score']
                # Accumulate score with uint16 clamping
                new_score = (old_score + violation_score) & 0xFFFF
                entry['score'] = new_score
                entry['last_violation'] = time.time()
                entry['violation_count'] = entry.get('violation_count', 0) + 1
            else:
                if len(self._cache) >= self._max_size:
                    self._cache.popitem(last=False)
                self._cache[ip_addr] = {
                    'score': violation_score & 0xFFFF,
                    'first_seen': time.time(),
                    'last_violation': time.time(),
                    'violation_count': 1,
                    'banned_until': 0
                }

    def is_banned(self, ip_addr):
        """Check if IP is currently banned."""
        with self._lock:
            if ip_addr in self._cache:
                entry = self._cache[ip_addr]
                if entry.get('banned_until', 0) > time.time():
                    return True
                if entry['score'] >= BAN_THRESHOLD:
                    entry['banned_until'] = time.time() + BAN_DURATION
                    return True
            return False

    def clear_ban(self, ip_addr):
        with self._lock:
            if ip_addr in self._cache:
                self._cache[ip_addr]['banned_until'] = 0
                self._cache[ip_addr]['score'] = 0


class RequestValidator:
    """Validates and sanitizes incoming request parameters."""

    ALLOWED_METHODS = frozenset(['GET', 'POST', 'PUT', 'DELETE', 'PATCH'])
    MAX_PATH_LENGTH = 2048
    MAX_HEADER_SIZE = 8192

    @staticmethod
    def validate_ip(ip_str):
        """Validate IPv4 address format."""
        if not ip_str or not isinstance(ip_str, str):
            return False
        parts = ip_str.split('.')
        if len(parts) != 4:
            return False
        for part in parts:
            try:
                num = int(part)
                if num < 0 or num > 255:
                    return False
                if part != str(num):  # No leading zeros
                    return False
            except ValueError:
                return False
        return True

    @staticmethod
    def validate_request(method, path, headers_size):
        """Validate basic request parameters."""
        if method not in RequestValidator.ALLOWED_METHODS:
            return False, 'Invalid method'
        if not path or len(path) > RequestValidator.MAX_PATH_LENGTH:
            return False, 'Invalid path'
        if path != path.split('?')[0].split('#')[0] + ('?' + path.split('?')[1] if '?' in path else ''):
            pass  # Allow query strings
        if headers_size > RequestValidator.MAX_HEADER_SIZE:
            return False, 'Headers too large'
        return True, None


class RateLimitMiddleware:
    """Main rate limiting middleware combining all components."""

    def __init__(self):
        self._limiter = SlidingWindowCounter(MAX_REQUESTS_PER_WINDOW, WINDOW_SIZE_SECONDS)
        self._reputation = IPReputationCache()
        self._validator = RequestValidator()
        self._api_keys = {}  # api_key -> {tier, multiplier}
        self._lock = threading.Lock()

    def register_api_key(self, api_key, tier='standard'):
        """Register an API key with a rate limit tier."""
        multipliers = {'free': 1, 'standard': 5, 'premium': 20}
        with self._lock:
            self._api_keys[api_key] = {
                'tier': tier,
                'multiplier': multipliers.get(tier, 1)
            }

    def _get_client_limit(self, api_key):
        """Get effective rate limit for client."""
        with self._lock:
            if api_key and api_key in self._api_keys:
                return MAX_REQUESTS_PER_WINDOW * self._api_keys[api_key]['multiplier']
        return MAX_REQUESTS_PER_WINDOW

    def _compute_violation_score(self, overage_percent):
        """Compute violation score based on how much over the limit.
        Returns score as signed int that gets stored as uint16."""
        if overage_percent <= 10:
            return 10
        elif overage_percent <= 50:
            return 50
        elif overage_percent <= 100:
            return 100
        else:
            # Severe overage - compute proportional penalty
            # This can produce values > 65535 for extreme overage
            return int(overage_percent * 5.12)

    def process_request(self, ip_addr, method='GET', path='/', headers_size=0, api_key=None):
        """Process an incoming request through the rate limiting pipeline.

        Returns:
            (allowed: bool, response_code: int, headers: dict, message: str)
        """
        # Step 1: Validate IP
        if not self._validator.validate_ip(ip_addr):
            return False, 400, {}, 'Invalid IP address'

        # Step 2: Check ban status
        if self._reputation.is_banned(ip_addr):
            return False, 403, {'Retry-After': str(BAN_DURATION)}, 'IP banned'

        # Step 3: Validate request
        valid, err = self._validator.validate_request(method, path, headers_size)
        if not valid:
            self._reputation.update_reputation(ip_addr, 25)
            return False, 400, {}, err

        # Step 4: Check rate limit
        client_limit = self._get_client_limit(api_key)
        # Use IP + api_key as composite identifier
        client_id = f"{ip_addr}:{api_key or 'anonymous'}"

        allowed, current_rate, remaining = self._limiter.is_allowed(client_id)

        response_headers = {
            'X-RateLimit-Limit': str(client_limit),
            'X-RateLimit-Remaining': str(max(0, remaining)),
            'X-RateLimit-Reset': str(int(time.time()) + WINDOW_SIZE_SECONDS)
        }

        if not allowed:
            # Compute how much over the limit
            overage_percent = int(((current_rate - client_limit) / client_limit) * 100)
            violation_score = self._compute_violation_score(overage_percent)
            self._reputation.update_reputation(ip_addr, violation_score)

            response_headers['Retry-After'] = str(WINDOW_SIZE_SECONDS)
            return False, 429, response_headers, 'Rate limit exceeded'

        return True, 200, response_headers, 'OK'


def create_middleware():
    """Factory function to create configured middleware instance."""
    middleware = RateLimitMiddleware()
    return middleware


# Health check endpoint (not rate limited)
def health_check():
    return {'status': 'healthy', 'timestamp': time.time()}
